/**
 * Execution tree computation for workflow node selection highlighting.
 *
 * Given a selected node, computes which nodes are upstream (ancestors)
 * and downstream (descendants) in the execution graph, plus which edges
 * connect them.
 */

export interface ExecutionTree {
  upstream: Set<string>;
  downstream: Set<string>;
  edgeIds: Set<string>;
}

/**
 * Compute the upstream and downstream execution tree from a selected node,
 * used for path highlighting in the workflow designer.
 *
 * The algorithm runs in three phases:
 *
 * 1. **Upstream BFS** — walks backwards from the selected node to collect
 *    all ancestor nodes that feed into it.
 *
 * 2. **Downstream BFS (with ALL-node fan-in)** — walks forward from the
 *    selected node to collect all reachable descendants. When an ALL-type
 *    node is encountered, a secondary backward BFS pulls in *every* incoming
 *    branch and its full ancestry, because ALL nodes require all inputs to
 *    be satisfied before they fire.
 *
 * 3. **Edge collection** — selects the edges that connect highlighted nodes,
 *    with a restriction on fan-in-only nodes (see below).
 *
 * @param selectedNodeId  The node the user clicked.
 * @param edges           All edges in the graph.
 * @param nodeTypes       Optional map of nodeId → NodeType string (e.g. 'or', 'all', 'any', …).
 */
export function getExecutionTree(
  selectedNodeId: string,
  edges: Array<{ id?: string; source: string; target: string }>,
  nodeTypes?: Map<string, string>,
): ExecutionTree {
  // Build adjacency structures
  const forwardAdj = new Map<string, string[]>(); // source → targets
  const reverseAdj = new Map<string, string[]>(); // target → sources
  const incomingEdges = new Map<string, Array<{ id?: string; source: string; target: string }>>();

  for (const edge of edges) {
    if (!forwardAdj.has(edge.source)) forwardAdj.set(edge.source, []);
    forwardAdj.get(edge.source)!.push(edge.target);

    if (!reverseAdj.has(edge.target)) reverseAdj.set(edge.target, []);
    reverseAdj.get(edge.target)!.push(edge.source);

    if (!incomingEdges.has(edge.target)) incomingEdges.set(edge.target, []);
    incomingEdges.get(edge.target)!.push(edge);
  }

  // --- Upstream (permissive BFS backwards) ---
  const upstream = new Set<string>();
  const queue: string[] = [];

  for (const src of reverseAdj.get(selectedNodeId) || []) {
    if (!upstream.has(src)) {
      upstream.add(src);
      queue.push(src);
    }
  }

  while (queue.length > 0) {
    const current = queue.shift()!;
    for (const src of reverseAdj.get(current) || []) {
      if (!upstream.has(src)) {
        upstream.add(src);
        queue.push(src);
      }
    }
  }

  // --- Downstream (BFS forward from selected node) ---
  // Follow all paths reachable from the selected node.
  // When an ALL node is reached, pull in ALL its incoming branches
  // (and their full upstream ancestry) so the complete fan-in is highlighted.
  const downstream = new Set<string>();
  // Tracks nodes added to `upstream` ONLY because of ALL-node fan-in,
  // not because they lie on the direct path from root to selected node.
  // Used later to restrict which edges these nodes may highlight.
  const allFanIn = new Set<string>();
  const allNodeIds = new Set<string>();     // the ALL nodes themselves
  const downQueue: string[] = [selectedNodeId];

  while (downQueue.length > 0) {
    const current = downQueue.shift()!;
    for (const target of forwardAdj.get(current) || []) {
      if (downstream.has(target) || target === selectedNodeId) continue;
      downstream.add(target);
      downQueue.push(target);

      // ALL-node fan-in: ALL nodes require *all* their inputs to be satisfied
      // before they can fire, so every source branch must be highlighted.
      // For each source of the ALL node that isn't already in the upstream set,
      // we BFS backwards to include its full ancestry — this ensures the
      // complete fan-in is visible, not just the single path we arrived from.
      if (nodeTypes?.get(target) === 'all') {
        allNodeIds.add(target);
        for (const src of reverseAdj.get(target) || []) {
          if (!upstream.has(src) && src !== selectedNodeId && !downstream.has(src)) {
            upstream.add(src);
            allFanIn.add(src);
            // BFS backwards from this ALL-node source to capture its full ancestry
            const backQueue: string[] = [src];
            while (backQueue.length > 0) {
              const back = backQueue.shift()!;
              for (const ancestor of reverseAdj.get(back) || []) {
                if (!upstream.has(ancestor) && ancestor !== selectedNodeId) {
                  upstream.add(ancestor);
                  allFanIn.add(ancestor);
                  backQueue.push(ancestor);
                }
              }
            }
          }
        }
      }
    }
  }

  const confirmed = new Set<string>([...upstream, selectedNodeId, ...downstream]);

  // --- Edge collection ---
  // Include an edge if both source and target are in the confirmed set.
  //
  // Special restriction for fan-in-only nodes: edges originating from a node
  // that was added *solely* because of ALL-node fan-in (i.e. it is in
  // `allFanIn` but NOT on the direct upstream/downstream path) are only
  // allowed to connect to the ALL node itself. Without this restriction,
  // a fan-in ancestor that also happens to connect to an unrelated
  // downstream node would cause over-highlighting of edges that aren't
  // part of the selected execution path.
  const edgeIds = new Set<string>();
  for (const edge of edges) {
    if (!edge.id) continue;
    if (!confirmed.has(edge.source) || !confirmed.has(edge.target)) continue;

    // Restrict fan-in-only nodes: their edges may only target the ALL node
    if (allFanIn.has(edge.source) && !allNodeIds.has(edge.target)) continue;

    edgeIds.add(edge.id);
  }

  return { upstream, downstream, edgeIds };
}
