export const WORKFLOW_BLUE = '#0082FA';
export const WORKFLOW_BLUE_LIGHT = 'rgba(0, 130, 250, 0.05)';
export const WORKFLOW_BLUE_TINT = '#F2F9FF';
export const WORKFLOW_GLOW = '#F4F4FA';
export const WORKFLOW_GRAY = '#C8C8D0';

// Card type accent colors (for borders, labels, fallback)
export const CARD_WHEN_COLOR = '#1E88E5';
export const CARD_AND_COLOR = '#43A047';
export const CARD_THEN_COLOR = '#FB8C00';

// Card type glow shadows (light mode)
export const CARD_WHEN_GLOW = 'rgba(33,150,243,0.18)';
export const CARD_AND_GLOW = 'rgba(76,175,80,0.18)';
export const CARD_THEN_GLOW = 'rgba(255,152,0,0.18)';

// Card type glow shadows (dark mode)
export const CARD_WHEN_GLOW_DARK = 'rgba(33,150,243,0.25)';
export const CARD_AND_GLOW_DARK = 'rgba(76,175,80,0.25)';
export const CARD_THEN_GLOW_DARK = 'rgba(255,152,0,0.25)';

// Helper to get fallback color config by card type
// (used when card has no own color from backend)
export function getCardTypeColors(cardType: string) {
  switch (cardType) {
    case 'when':
      return {
        glow: CARD_WHEN_GLOW,
        glowDark: CARD_WHEN_GLOW_DARK,
        accent: CARD_WHEN_COLOR,
      };
    case 'and':
      return {
        glow: CARD_AND_GLOW,
        glowDark: CARD_AND_GLOW_DARK,
        accent: CARD_AND_COLOR,
      };
    case 'then':
    default:
      return {
        glow: CARD_THEN_GLOW,
        glowDark: CARD_THEN_GLOW_DARK,
        accent: CARD_THEN_COLOR,
      };
  }
}
