<template>
  <div :class="['advanced-workflow-card', { 'advanced-workflow-card--dark': $q.dark.isActive }]">
    <div
      class="taskCard taskCard-bg"
      :class="[
        isDialog ? 'cursor-pointer' : 'cursor-default',
      ]"
      :style="cardCssVars"
      @click="onCardClick(item)"
      @mouseenter="isHovering = true"
      @mouseleave="isHovering = false"
    >
      <!-- Squircle icon -->
      <div
        class="card-icon"
        :style="iconStyle"
        @click.stop="testCard"
      >
        <q-icon
          v-if="showPlayIcon"
          name="play_arrow"
          color="white"
          size="sm"
        />
        <i
          v-else
          v-html="item.svg"
          class="svg-icon"
          :class="{ 'svg-icon--light': isDarkBackground }"
        ></i>
      </div>

      <!-- Text content -->
      <div class="card-content">
        <!-- Type row: label · category · version pill -->
        <div class="card-type-row">
          <span
            v-if="cardType && !isDialog"
            class="card-type-label"
            :style="{ color: readableAccentColor }"
          >{{ $t(cardType) }}</span>
          <span v-if="cardType && !isDialog" class="card-type-separator">·</span>
          <span class="card-category">{{ $t(item.category) }}</span>

          <!-- Version pill (canvas only) -->
          <span
            v-if="!isDialog && item.card_version"
            class="card-version-pill"
            :style="versionPillStyle"
            @click.stop.prevent
          >
            v{{ item.card_version }} <q-icon name="expand_more" size="12px" class="version-chevron" />
            <q-menu>
              <q-list @click.stop.prevent>
                <q-item
                  clickable
                  v-close-popup
                  @click="
                    $emit('changeCardVersion', version, item, itemIndex, cardType, nodeId)
                  "
                  v-for="version in availableVersions"
                  :key="version"
                >
                  <q-item-section>
                    <q-item-label>v{{ version }}</q-item-label>
                  </q-item-section>
                </q-item>
              </q-list>
            </q-menu>
          </span>
        </div>

        <!-- Description -->
        <p class="card-description">
          <q-icon v-if="item.isMissingCard" name="warning" color="warning" size="xs" class="q-mr-xs">
            <q-tooltip>{{ item.missingCardTooltip }}</q-tooltip>
          </q-icon>
          <template v-if="!dataArray || dataArray.length < 1">
            {{ cardPlainText }}
          </template>

          <template v-else>
            <template v-for="(str, index) in dataArray" :key="index">
              <template v-if="renderBadge(str)">
                <Badge :item="item" :variable="str" :isDialog="isDialog" />
              </template>
              <template v-else-if="renderTextTranslation(str)">
                {{ $t(str) }}
              </template>
              <template v-else>
                {{ str + ' ' }}
              </template>
            </template>
          </template>
        </p>
      </div>
    </div>
  </div>
</template>

<script lang="ts">
import { defineComponent } from 'vue';
import Badge from 'src/pages/WorkflowBuilder/badge.vue';
import helperUtil from 'src/utils/helperUtil';
import helperMixin from 'src/mixins/helperMixin';
import {
  workflowSplitDelimiter,
  workflowTranslationDelimiter,
} from 'src/constants';
import { resolveCardPlainText, prepareData as gcfprepareData } from 'src/pages/WorkflowBuilder/generic_card_functions';
import { getCardTypeColors } from 'src/pages/WorkflowBuilder/WorkflowComponnets/workflowColors';

export default defineComponent({
  name: 'AdvancedWorkflowCard',
  emits: [
    'onCardClick',
    'removeNode',
    'duplicateNode',
    'copyNode',
    'changeCardVersion',
    'createNote',
    'testCard',
  ],
  mixins: [helperUtil, helperMixin],
  components: { Badge },
  props: {
    isDialog: {
      type: Boolean,
      default: true,
    },
    itemIndex: {
      type: Number,
      default: null,
    },
    nodeId: {
      type: String,
      default: '',
    },
    cardType: {
      type: String,
      default: '',
    },
    parentSvg: {
      type: String,
      default: '',
    },
    color: {
      type: String,
      default: '',
    },
    item: {
      type: Object,
      default: {
        category: '',
        id: '',
        text: '',
        toolTip: '',
        card_version: '',
      } as any,
    },
  },
  data() {
    return {
      showItemPanel: false,
      dataArray: [] as string[],
      isHovering: false,
    };
  },

  computed: {
    /** Resolved plain-text for cards with no variable markers (partner card aware) */
    cardPlainText(): string {
      return resolveCardPlainText(this.item);
    },
    isConditionCard() {
      return this.cardType === 'when' || this.cardType === 'and';
    },
    showPlayIcon() {
      return this.isConditionCard && this.isHovering;
    },
    availableVersions() {
      const versions = this.item.all_versions || [];
      if (this.isConditionCard) {
        return versions.filter((v: number) => v >= 2);
      }
      return versions;
    },
    isDarkBackground(): boolean {
      const rgb = this.parseHex(this.color);
      if (!rgb) return true;
      // Threshold 0.65 — most colors get white icons, only very light ones keep dark
      const luminance = (0.299 * rgb[0] + 0.587 * rgb[1] + 0.114 * rgb[2]) / 255;
      return luminance < 0.65;
    },
    typeColors() {
      return getCardTypeColors(this.cardType);
    },
    cardCssVars(): Record<string, string> {
      // Use the card's own color for accent border and glow,
      // falling back to type-based colors if no card color
      const baseColor = this.color || this.typeColors.accent;
      return {
        '--card-accent': baseColor,
        '--card-glow-color': this.hexToRgba(baseColor, 0.18),
        '--card-glow-color-dark': this.hexToRgba(baseColor, 0.25),
      };
    },
    iconStyle(): Record<string, string> {
      if (this.showPlayIcon) {
        return {
          background: 'linear-gradient(135deg, #42A5F5, #1565C0)',
          boxShadow: '0 4px 12px rgba(33,150,243,0.3)',
          cursor: 'pointer',
        };
      }
      // Use the card's own color (from backend svg_background_color)
      // and create a gradient by darkening it for the bottom-right
      const baseColor = this.color || '#999';
      return {
        background: `linear-gradient(135deg, ${baseColor}, ${this.darkenColor(baseColor, 0.25)})`,
        boxShadow: `0 4px 12px ${this.hexToRgba(baseColor, 0.3)}`,
        cursor: this.isConditionCard ? 'pointer' : 'default',
      };
    },
    readableAccentColor(): string {
      const baseColor = this.color || this.typeColors.accent;
      return this.isLightColor(baseColor)
        ? this.darkenColor(baseColor, 0.45)
        : baseColor;
    },
    versionPillStyle(): Record<string, string> {
      const baseColor = this.color || this.typeColors.accent;
      return {
        color: this.readableAccentColor,
        backgroundColor: this.hexToRgba(baseColor, 0.12),
        border: `1px solid ${this.hexToRgba(baseColor, 0.2)}`,
      };
    },
  },

  mounted() {
    this.prepareData();
  },

  watch: {
    item: {
      handler() {
        this.dataArray = [];
        this.prepareData();
      },
      deep: true,
    },
  },

  methods: {
    parseHex(hex: string): [number, number, number] | null {
      if (!hex || !hex.startsWith('#') || hex.length < 7) return null;
      return [
        parseInt(hex.slice(1, 3), 16),
        parseInt(hex.slice(3, 5), 16),
        parseInt(hex.slice(5, 7), 16),
      ];
    },
    hexToRgba(hex: string, alpha: number): string {
      const rgb = this.parseHex(hex);
      if (!rgb) return `rgba(150,150,150,${alpha})`;
      return `rgba(${rgb[0]},${rgb[1]},${rgb[2]},${alpha})`;
    },
    isLightColor(hex: string): boolean {
      const rgb = this.parseHex(hex);
      if (!rgb) return false;
      const luminance = (0.299 * rgb[0] + 0.587 * rgb[1] + 0.114 * rgb[2]) / 255;
      return luminance > 0.55;
    },
    darkenColor(hex: string, amount: number): string {
      const rgb = this.parseHex(hex);
      if (!rgb) return '#666666';
      const d = rgb.map(c => Math.max(0, Math.round(c * (1 - amount))));
      return `#${d.map(c => c.toString(16).padStart(2, '0')).join('')}`;
    },
    testCard() {
      if (this.isConditionCard) {
        this.$emit('testCard', {
          card: this.item,
          nodeId: this.nodeId,
          cardType: this.cardType,
        });
      }
    },

    renderBadge(str: string) {
      return str.startsWith(workflowSplitDelimiter);
    },

    renderTextTranslation(str: string) {
      return str.startsWith(workflowTranslationDelimiter);
    },

    prepareData() {
      this.dataArray = gcfprepareData(this.item);
    },
    onCardClick(item: any) {
      if (!this.isDialog) {
        return;
      }

      item.parentColor = this.color;

      this.$emit('onCardClick', item);
    },
  },
  setup() {
    return {};
  },
});
</script>

